 let mut a=vec![rw(master)];a.extend(lanes.iter().copied().map(rw));a.extend([ro(mint),rw(vault),ro(token),meta(payer,true,true),ro(system)]);
 let slot=q["activation_slot"].as_u64().unwrap();let loader=Pubkey::from_str(LOADER)?;
